  <style>
    *,*::before,*::after{box-sizing:border-box;margin:0;padding:0}

    :root {
      --red: #C41E3A;
      --red-dark: #A01830;
      --red-light: #E8364F;
      --navy: #1B3A5C;
      --navy-dark: #122840;
      --navy-light: #2A5580;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --gray-700: #374151;
      --gray-800: #1F2937;
      --gray-900: #111827;
      --warm-bg: #FDF8F6;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -2px rgba(0,0,0,0.1);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.1), 0 4px 6px -4px rgba(0,0,0,0.1);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.1), 0 8px 10px -6px rgba(0,0,0,0.1);
      --radius: 8px;
      --radius-lg: 12px;
      --transition: 0.3s ease;
    }

    html {
      scroll-behavior: smooth;
      font-size: 16px;
    }

    body {
      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
      color: var(--gray-800);
      line-height: 1.6;
      background: var(--white);
      overflow-x: hidden;
    }

    img { max-width: 100%; height: auto; display: block; }
    a { color: inherit; text-decoration: none; }
    button { cursor: pointer; font-family: inherit; }
    ul { list-style: none; }

    .container {
      width: 100%;
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
    }

    /* ===== HEADER ===== */
    .header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      transition: box-shadow var(--transition);
    }

    .header.scrolled {
      box-shadow: var(--shadow-md);
    }

    .header__utility {
      background: var(--navy);
      color: var(--white);
      font-size: 0.8125rem;
      padding: 6px 0;
    }

    .header__utility .container {
      display: flex;
      justify-content: flex-end;
      gap: 20px;
    }

    .header__utility a {
      color: rgba(255,255,255,0.85);
      transition: color var(--transition);
    }

    .header__utility a:hover {
      color: var(--white);
    }

    .header__main {
      padding: 12px 0;
    }

    .header__main .container {
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .header__logo {
      display: flex;
      align-items: center;
      gap: 12px;
      font-weight: 800;
      font-size: 1.25rem;
      color: var(--navy);
    }

    .header__logo-icon {
      width: 44px;
      height: 44px;
      background: var(--red);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--white);
      font-size: 1.25rem;
      flex-shrink: 0;
    }

    .header__nav {
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .header__nav a {
      padding: 8px 14px;
      font-size: 0.9375rem;
      font-weight: 500;
      color: var(--gray-700);
      border-radius: var(--radius);
      transition: color var(--transition), background var(--transition);
    }

    .header__nav a:hover {
      color: var(--red);
      background: var(--gray-50);
    }

    .header__donate-btn {
      background: var(--red);
      color: var(--white) !important;
      padding: 10px 24px !important;
      border-radius: 50px !important;
      font-weight: 600 !important;
      transition: background var(--transition), transform var(--transition) !important;
    }

    .header__donate-btn:hover {
      background: var(--red-dark) !important;
      color: var(--white) !important;
      transform: translateY(-1px);
    }

    .hamburger {
      display: none;
      background: none;
      border: none;
      padding: 8px;
      flex-direction: column;
      gap: 5px;
      z-index: 1100;
    }

    .hamburger span {
      display: block;
      width: 26px;
      height: 3px;
      background: var(--gray-800);
      border-radius: 3px;
      transition: var(--transition);
    }

    .hamburger.active span:nth-child(1) {
      transform: rotate(45deg) translate(5px, 6px);
    }

    .hamburger.active span:nth-child(2) {
      opacity: 0;
    }

    .hamburger.active span:nth-child(3) {
      transform: rotate(-45deg) translate(5px, -6px);
    }

    /* ===== HERO ===== */
    .hero {
      margin-top: 100px;
      padding: 80px 0 100px;
      background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 100%);
      color: var(--white);
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 320"><path fill="rgba(255,255,255,0.03)" d="M0,160L48,170.7C96,181,192,203,288,192C384,181,480,139,576,128C672,117,768,139,864,170.7C960,203,1056,245,1152,240C1248,235,1344,181,1392,154.7L1440,128L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"/></svg>') no-repeat bottom center;
      background-size: cover;
      pointer-events: none;
    }

    .hero .container {
      position: relative;
      z-index: 1;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .hero__content h1 {
      font-size: clamp(2.25rem, 5vw, 3.5rem);
      font-weight: 800;
      line-height: 1.15;
      margin-bottom: 20px;
      letter-spacing: -0.02em;
    }

    .hero__content p {
      font-size: 1.125rem;
      line-height: 1.7;
      color: rgba(255,255,255,0.85);
      margin-bottom: 36px;
      max-width: 540px;
    }

    .hero__cta {
      display: flex;
      gap: 16px;
      flex-wrap: wrap;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 14px 32px;
      border-radius: 50px;
      font-size: 1rem;
      font-weight: 600;
      border: none;
      transition: all var(--transition);
      cursor: pointer;
    }

    .btn--primary {
      background: var(--red);
      color: var(--white);
    }

    .btn--primary:hover {
      background: var(--red-dark);
      transform: translateY(-2px);
      box-shadow: 0 8px 25px rgba(196,30,58,0.4);
    }

    .btn--secondary {
      background: transparent;
      color: var(--white);
      border: 2px solid rgba(255,255,255,0.4);
    }

    .btn--secondary:hover {
      border-color: var(--white);
      background: rgba(255,255,255,0.1);
      transform: translateY(-2px);
    }

    .hero__image {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: rgba(255,255,255,0.1);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .hero__image-placeholder {
      width: 100%;
      height: 100%;
      background: linear-gradient(135deg, rgba(196,30,58,0.3), rgba(27,58,92,0.5));
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 12px;
      font-size: 0.875rem;
      color: rgba(255,255,255,0.7);
      border-radius: var(--radius-lg);
    }

    .hero__image-placeholder svg {
      width: 64px;
      height: 64px;
      opacity: 0.5;
    }

    /* ===== SECTION COMMONS ===== */
    .section {
      padding: 80px 0;
    }

    .section--gray {
      background: var(--gray-50);
    }

    .section--warm {
      background: var(--warm-bg);
    }

    .section--dark {
      background: var(--navy);
      color: var(--white);
    }

    .section__header {
      text-align: center;
      max-width: 700px;
      margin: 0 auto 56px;
    }

    .section__label {
      display: inline-block;
      font-size: 0.8125rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.1em;
      color: var(--red);
      margin-bottom: 12px;
    }

    .section--dark .section__label {
      color: var(--red-light);
    }

    .section__title {
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      font-weight: 800;
      line-height: 1.2;
      letter-spacing: -0.02em;
      margin-bottom: 16px;
    }

    .section__subtitle {
      font-size: 1.0625rem;
      color: var(--gray-500);
      line-height: 1.7;
    }

    .section--dark .section__subtitle {
      color: rgba(255,255,255,0.7);
    }

    /* ===== MISSION ===== */
    .mission__grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 60px;
      align-items: center;
    }

    .mission__text h2 {
      font-size: 2rem;
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 20px;
      line-height: 1.25;
    }

    .mission__text p {
      font-size: 1.0625rem;
      color: var(--gray-600);
      line-height: 1.8;
      margin-bottom: 16px;
    }

    .mission__image {
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 4/3;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .mission__image-placeholder {
      width: 100%;
      height: 100%;
      background: linear-gradient(135deg, var(--gray-100), var(--gray-200));
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      gap: 8px;
      color: var(--gray-400);
      font-size: 0.875rem;
    }

    .mission__image-placeholder svg {
      width: 48px;
      height: 48px;
    }

    /* ===== IMPACT STATS ===== */
    .impact {
      background: linear-gradient(135deg, var(--navy) 0%, var(--navy-dark) 100%);
      color: var(--white);
      padding: 80px 0;
    }

    .impact__grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 40px;
      text-align: center;
    }

    .impact__item {
      padding: 24px 16px;
    }

    .impact__icon {
      width: 56px;
      height: 56px;
      margin: 0 auto 16px;
      background: rgba(196,30,58,0.2);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .impact__icon svg {
      width: 28px;
      height: 28px;
      fill: var(--red-light);
    }

    .impact__number {
      font-size: clamp(2rem, 4vw, 3rem);
      font-weight: 800;
      line-height: 1.1;
      margin-bottom: 4px;
      letter-spacing: -0.02em;
    }

    .impact__suffix {
      font-size: clamp(1rem, 2vw, 1.25rem);
      font-weight: 600;
      opacity: 0.85;
    }

    .impact__label {
      font-size: 0.9375rem;
      color: rgba(255,255,255,0.7);
      margin-top: 4px;
    }

    .impact__footnote {
      text-align: center;
      margin-top: 48px;
      font-size: 1rem;
      color: rgba(255,255,255,0.6);
      max-width: 700px;
      margin-left: auto;
      margin-right: auto;
    }

    /* ===== PROGRAMS ACCORDION ===== */
    .programs__list {
      max-width: 800px;
      margin: 0 auto;
    }

    .accordion__item {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      margin-bottom: 12px;
      overflow: hidden;
      transition: box-shadow var(--transition);
    }

    .accordion__item:hover {
      box-shadow: var(--shadow-sm);
    }

    .accordion__header {
      width: 100%;
      display: flex;
      align-items: center;
      gap: 16px;
      padding: 20px 24px;
      background: var(--white);
      border: none;
      font-size: 1.0625rem;
      font-weight: 600;
      color: var(--gray-800);
      text-align: left;
      cursor: pointer;
      transition: background var(--transition);
    }

    .accordion__header:hover {
      background: var(--gray-50);
    }

    .accordion__icon-wrapper {
      width: 40px;
      height: 40px;
      background: var(--red);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }

    .accordion__icon-wrapper svg {
      width: 20px;
      height: 20px;
      fill: var(--white);
    }

    .accordion__chevron {
      margin-left: auto;
      width: 20px;
      height: 20px;
      transition: transform var(--transition);
      flex-shrink: 0;
      color: var(--gray-400);
    }

    .accordion__item.active .accordion__chevron {
      transform: rotate(180deg);
    }

    .accordion__body {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.4s ease, padding 0.3s ease;
    }

    .accordion__item.active .accordion__body {
      max-height: 300px;
    }

    .accordion__content {
      padding: 0 24px 20px 80px;
      font-size: 0.9625rem;
      color: var(--gray-600);
      line-height: 1.7;
    }

    /* ===== GET INVOLVED ===== */
    .involved__grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 32px;
    }

    .involved__card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 40px 32px;
      text-align: center;
      box-shadow: var(--shadow-md);
      transition: transform var(--transition), box-shadow var(--transition);
      border: 1px solid var(--gray-100);
    }

    .involved__card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-xl);
    }

    .involved__card-icon {
      width: 64px;
      height: 64px;
      margin: 0 auto 20px;
      background: var(--warm-bg);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .involved__card-icon svg {
      width: 30px;
      height: 30px;
      fill: var(--red);
    }

    .involved__card h3 {
      font-size: 1.25rem;
      font-weight: 700;
      margin-bottom: 12px;
      color: var(--navy);
    }

    .involved__card p {
      font-size: 0.9375rem;
      color: var(--gray-500);
      line-height: 1.7;
      margin-bottom: 24px;
    }

    .btn--outline {
      background: transparent;
      color: var(--red);
      border: 2px solid var(--red);
      padding: 10px 24px;
      font-size: 0.9375rem;
    }

    .btn--outline:hover {
      background: var(--red);
      color: var(--white);
      transform: translateY(-2px);
    }

    /* ===== NEWS CAROUSEL ===== */
    .news__carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .news__track {
      display: flex;
      transition: transform 0.5s ease;
    }

    .news__card {
      min-width: calc(33.333% - 22px);
      margin-right: 32px;
      background: var(--white);
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-md);
      border: 1px solid var(--gray-100);
      transition: transform var(--transition), box-shadow var(--transition);
    }

    .news__card:hover {
      transform: translateY(-4px);
      box-shadow: var(--shadow-lg);
    }

    .news__card-image {
      height: 200px;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-400);
      font-size: 0.8125rem;
    }

    .news__card-image svg {
      width: 40px;
      height: 40px;
      margin-bottom: 8px;
    }

    .news__card-body {
      padding: 24px;
    }

    .news__card-tag {
      display: inline-block;
      font-size: 0.75rem;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.05em;
      color: var(--red);
      margin-bottom: 10px;
    }

    .news__card-body h3 {
      font-size: 1.125rem;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 10px;
      line-height: 1.35;
    }

    .news__card-body p {
      font-size: 0.875rem;
      color: var(--gray-500);
      line-height: 1.65;
    }

    .news__nav {
      display: flex;
      justify-content: center;
      gap: 16px;
      margin-top: 40px;
    }

    .news__btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      border: 2px solid var(--gray-300);
      background: var(--white);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition);
      color: var(--gray-600);
    }

    .news__btn:hover {
      border-color: var(--red);
      color: var(--red);
      background: var(--warm-bg);
    }

    .news__btn:disabled {
      opacity: 0.4;
      cursor: not-allowed;
    }

    .news__btn svg {
      width: 20px;
      height: 20px;
    }

    .news__dots {
      display: flex;
      justify-content: center;
      gap: 8px;
      margin-top: 20px;
    }

    .news__dot {
      width: 10px;
      height: 10px;
      border-radius: 50%;
      background: var(--gray-300);
      border: none;
      cursor: pointer;
      transition: background var(--transition), transform var(--transition);
    }

    .news__dot.active {
      background: var(--red);
      transform: scale(1.2);
    }

    /* ===== DONATE CTA ===== */
    .donate-cta {
      background: linear-gradient(135deg, var(--red) 0%, var(--red-dark) 100%);
      color: var(--white);
      padding: 80px 0;
      text-align: center;
    }

    .donate-cta h2 {
      font-size: clamp(1.75rem, 3.5vw, 2.5rem);
      font-weight: 800;
      margin-bottom: 16px;
    }

    .donate-cta p {
      font-size: 1.0625rem;
      max-width: 600px;
      margin: 0 auto 36px;
      color: rgba(255,255,255,0.9);
      line-height: 1.7;
    }

    .btn--white {
      background: var(--white);
      color: var(--red);
      padding: 16px 40px;
      font-size: 1.0625rem;
    }

    .btn--white:hover {
      background: var(--gray-50);
      transform: translateY(-2px);
      box-shadow: 0 8px 25px rgba(0,0,0,0.2);
    }

    /* ===== FOOTER ===== */
    .footer {
      background: var(--gray-900);
      color: var(--gray-300);
      padding: 64px 0 0;
    }

    .footer__grid {
      display: grid;
      grid-template-columns: 1.5fr repeat(4, 1fr);
      gap: 40px;
      margin-bottom: 48px;
    }

    .footer__brand p {
      font-size: 0.875rem;
      line-height: 1.7;
      color: var(--gray-400);
      margin-top: 12px;
    }

    .footer__brand-name {
      font-size: 1.25rem;
      font-weight: 800;
      color: var(--white);
      display: flex;
      align-items: center;
      gap: 10px;
    }

    .footer__brand-icon {
      width: 36px;
      height: 36px;
      background: var(--red);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1rem;
      color: var(--white);
      flex-shrink: 0;
    }

    .footer__social {
      display: flex;
      gap: 12px;
      margin-top: 20px;
    }

    .footer__social a {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      background: rgba(255,255,255,0.1);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: background var(--transition);
      color: var(--gray-400);
    }

    .footer__social a:hover {
      background: var(--red);
      color: var(--white);
    }

    .footer__col h4 {
      font-size: 0.875rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer__col a {
      display: block;
      font-size: 0.875rem;
      color: var(--gray-400);
      padding: 4px 0;
      transition: color var(--transition);
    }

    .footer__col a:hover {
      color: var(--white);
    }

    .footer__bottom {
      border-top: 1px solid rgba(255,255,255,0.1);
      padding: 24px 0;
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 12px;
      font-size: 0.8125rem;
      color: var(--gray-500);
    }

    /* ===== DONATION MODAL ===== */
    .modal-overlay {
      position: fixed;
      inset: 0;
      z-index: 9999;
      background: rgba(0,0,0,0.6);
      backdrop-filter: blur(4px);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.3s, visibility 0.3s;
      padding: 20px;
    }

    .modal-overlay.active {
      opacity: 1;
      visibility: visible;
    }

    .modal {
      background: var(--white);
      border-radius: var(--radius-lg);
      width: 100%;
      max-width: 520px;
      max-height: 90vh;
      overflow-y: auto;
      transform: scale(0.95) translateY(20px);
      transition: transform 0.3s;
      box-shadow: var(--shadow-xl);
    }

    .modal-overlay.active .modal {
      transform: scale(1) translateY(0);
    }

    .modal__header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding: 24px 28px 0;
    }

    .modal__header h2 {
      font-size: 1.5rem;
      font-weight: 800;
      color: var(--navy);
    }

    .modal__close {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      border: none;
      background: var(--gray-100);
      font-size: 1.25rem;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--gray-500);
      transition: all var(--transition);
    }

    .modal__close:hover {
      background: var(--gray-200);
      color: var(--gray-800);
    }

    .modal__body {
      padding: 24px 28px 28px;
    }

    .modal__note {
      font-size: 0.875rem;
      color: var(--gray-500);
      margin-bottom: 24px;
      line-height: 1.6;
    }

    .donate-amounts {
      display: grid;
      grid-template-columns: repeat(2, 1fr);
      gap: 12px;
      margin-bottom: 20px;
    }

    .donate-amount {
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      padding: 16px;
      background: var(--white);
      cursor: pointer;
      transition: all var(--transition);
      text-align: center;
    }

    .donate-amount:hover {
      border-color: var(--red);
    }

    .donate-amount.selected {
      border-color: var(--red);
      background: rgba(196,30,58,0.05);
    }

    .donate-amount__value {
      font-size: 1.5rem;
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 4px;
    }

    .donate-amount__impact {
      font-size: 0.75rem;
      color: var(--gray-500);
      line-height: 1.4;
    }

    .donate-custom {
      margin-bottom: 24px;
    }

    .donate-custom label {
      display: block;
      font-size: 0.8125rem;
      font-weight: 600;
      color: var(--gray-600);
      margin-bottom: 8px;
    }

    .donate-custom__input-wrap {
      position: relative;
    }

    .donate-custom__input-wrap span {
      position: absolute;
      left: 16px;
      top: 50%;
      transform: translateY(-50%);
      font-size: 1.125rem;
      font-weight: 700;
      color: var(--gray-400);
    }

    .donate-custom input {
      width: 100%;
      padding: 14px 16px 14px 32px;
      border: 2px solid var(--gray-200);
      border-radius: var(--radius);
      font-size: 1.125rem;
      font-weight: 600;
      color: var(--gray-800);
      outline: none;
      transition: border-color var(--transition);
    }

    .donate-custom input:focus {
      border-color: var(--red);
    }

    .donate-custom input::placeholder {
      color: var(--gray-300);
      font-weight: 400;
    }

    .modal__efficiency {
      display: flex;
      align-items: center;
      gap: 10px;
      padding: 12px 16px;
      background: var(--gray-50);
      border-radius: var(--radius);
      margin-bottom: 20px;
      font-size: 0.8125rem;
      color: var(--gray-600);
    }

    .modal__efficiency strong {
      color: var(--navy);
    }

    .modal__submit {
      width: 100%;
      padding: 16px;
      background: var(--red);
      color: var(--white);
      border: none;
      border-radius: 50px;
      font-size: 1.0625rem;
      font-weight: 700;
      cursor: pointer;
      transition: background var(--transition), transform var(--transition);
    }

    .modal__submit:hover {
      background: var(--red-dark);
      transform: translateY(-1px);
    }

    /* ===== MOBILE NAV DRAWER ===== */
    .mobile-nav {
      position: fixed;
      top: 0;
      right: 0;
      bottom: 0;
      width: 300px;
      max-width: 85vw;
      background: var(--white);
      z-index: 1050;
      transform: translateX(100%);
      transition: transform 0.35s ease;
      box-shadow: var(--shadow-xl);
      padding: 80px 24px 24px;
      overflow-y: auto;
    }

    .mobile-nav.open {
      transform: translateX(0);
    }

    .mobile-nav__backdrop {
      position: fixed;
      inset: 0;
      background: rgba(0,0,0,0.5);
      z-index: 1040;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.3s, visibility 0.3s;
    }

    .mobile-nav__backdrop.open {
      opacity: 1;
      visibility: visible;
    }

    .mobile-nav a {
      display: block;
      padding: 14px 0;
      font-size: 1.0625rem;
      font-weight: 500;
      color: var(--gray-700);
      border-bottom: 1px solid var(--gray-100);
      transition: color var(--transition);
    }

    .mobile-nav a:hover {
      color: var(--red);
    }

    .mobile-nav .btn--primary {
      width: 100%;
      text-align: center;
      margin-top: 20px;
      display: block;
      border: none;
    }

    /* ===== RESPONSIVE ===== */
    @media (max-width: 1024px) {
      .hero .container {
        grid-template-columns: 1fr;
        gap: 40px;
      }
      .hero__image {
        max-width: 500px;
        margin: 0 auto;
      }
      .mission__grid {
        grid-template-columns: 1fr;
        gap: 40px;
      }
      .footer__grid {
        grid-template-columns: repeat(2, 1fr);
      }
    }

    @media (max-width: 768px) {
      .header__utility {
        display: none;
      }
      .header__nav {
        display: none;
      }
      .hamburger {
        display: flex;
      }
      .hero {
        margin-top: 68px;
        padding: 48px 0 64px;
      }
      .section {
        padding: 56px 0;
      }
      .impact__grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 24px;
      }
      .involved__grid {
        grid-template-columns: 1fr;
        gap: 20px;
      }
      .news__card {
        min-width: calc(100% - 0px);
        margin-right: 0;
      }
      .news__track {
        gap: 16px;
      }
      .footer__grid {
        grid-template-columns: 1fr;
        gap: 32px;
      }
      .footer__bottom {
        flex-direction: column;
        text-align: center;
      }
      .donate-amounts {
        grid-template-columns: 1fr 1fr;
      }
    }

    @media (max-width: 480px) {
      .hero__content h1 {
        font-size: 1.875rem;
      }
      .hero__cta {
        flex-direction: column;
      }
      .hero__cta .btn {
        width: 100%;
        justify-content: center;
      }
      .impact__grid {
        grid-template-columns: 1fr 1fr;
        gap: 16px;
      }
      .impact__number {
        font-size: 1.75rem;
      }
    }

    /* Animated counter */
    .counter-animate {
      opacity: 0;
      transform: translateY(20px);
      transition: opacity 0.6s ease, transform 0.6s ease;
    }
    .counter-animate.visible {
      opacity: 1;
      transform: translateY(0);
    }
  </style>
</head>
<body>

  <!-- ===== HEADER ===== -->
  <header class="header" id="header">
    <div class="header__utility">
      <div class="container">
        <a href="#signin">Sign In</a>
        <a href="#contact">Contact Us</a>
        <a href="#espanol" lang="es">Espa&ntilde;ol</a>
      </div>
    </div>
    <div class="header__main">
      <div class="container">
        <a href="#" class="header__logo" aria-label="Global Aid Alliance home">
          <span class="header__logo-icon" aria-hidden="true">&#10010;</span>
          <span>Global Aid Alliance</span>
        </a>
        <nav class="header__nav" aria-label="Main navigation">
          <a href="#mission">About Us</a>
          <a href="#programs">Disaster Relief</a>
          <a href="#programs">Programs &amp; Services</a>
          <a href="#involved">Volunteer</a>
          <a href="#contact">Find Local Chapter</a>
          <a href="#" class="header__donate-btn" data-donate-trigger>Donate</a>
        </nav>
        <button class="hamburger" id="hamburgerBtn" aria-label="Open menu" aria-expanded="false">
          <span></span>
          <span></span>
          <span></span>
        </button>
      </div>
    </div>
  </header>

  <!-- Mobile Nav Drawer -->
  <div class="mobile-nav__backdrop" id="mobileBackdrop"></div>
  <nav class="mobile-nav" id="mobileNav" aria-label="Mobile navigation">
    <a href="#mission" class="mobile-nav__link">About Us</a>
    <a href="#programs" class="mobile-nav__link">Disaster Relief</a>
    <a href="#programs" class="mobile-nav__link">Programs &amp; Services</a>
    <a href="#involved" class="mobile-nav__link">Volunteer</a>
    <a href="#contact" class="mobile-nav__link">Find Local Chapter</a>
    <a href="#" class="btn btn--primary mobile-nav__link" data-donate-trigger>Donate Now</a>
  </nav>

  <!-- ===== HERO ===== -->
  <section class="hero" id="hero">
    <div class="container">
      <div class="hero__content">
        <h1>When Disaster Strikes, We're There</h1>
        <p>From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.</p>
        <div class="hero__cta">
          <button class="btn btn--primary" data-donate-trigger>Donate Now</button>
          <a href="#involved" class="btn btn--secondary">Become a Volunteer</a>
        </div>
      </div>
      <div class="hero__image">
        <div class="hero__image-placeholder" role="img" aria-label="Humanitarian relief workers distributing supplies to families in need">
          <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" stroke-linejoin="round" d="M15 19.128a9.38 9.38 0 002.625.372 9.337 9.337 0 004.121-.952 4.125 4.125 0 00-7.533-2.493M15 19.128v-.003c0-1.113-.285-2.16-.786-3.07M15 19.128v.106A12.318 12.318 0 018.624 21c-2.331 0-4.512-.645-6.374-1.766l-.001-.109a6.375 6.375 0 0111.964-3.07M12 6.375a3.375 3.375 0 11-6.75 0 3.375 3.375 0 016.75 0zm8.25 2.25a2.625 2.625 0 11-5.25 0 2.625 2.625 0 015.25 0z"/></svg>
          <span>Relief workers helping families</span>
        </div>
      </div>
    </div>
  </section>

  <!-- ===== MISSION ===== -->
  <section class="section" id="mission">
    <div class="container">
      <div class="mission__grid">
        <div class="mission__text">
          <h2>Our Mission</h2>
          <p>Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.</p>
          <p>We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most &mdash; regardless of race, religion, nationality, or political affiliation. From the first hours of a disaster to the years of recovery that follow, we stand with affected communities every step of the way.</p>
        </div>
        <div class="mission__image">
          <div class="mission__image-placeholder" role="img" aria-label="Diverse community members and volunteers working together after a disaster">
            <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="1.5"><path stroke-linecap="round" stroke-linejoin="round" d="M21 8.25c0-2.485-2.099-4.5-4.688-4.5-1.935 0-3.597 1.126-4.312 2.733-.715-1.607-2.377-2.733-4.313-2.733C5.1 3.75 3 5.765 3 8.25c0 7.22 9 12 9 12s9-4.78 9-12z"/></svg>
            <span>Community resilience</span>
          </div>
        </div>
      </div>
    </div>
  </section>

  <!-- ===== IMPACT STATS ===== -->
  <section class="impact" id="impact">
    <div class="container">
      <div class="section__header">
        <span class="section__label" style="color: var(--red-light);">Our Impact</span>
        <h2 class="section__title" style="color: var(--white);">Making a Measurable Difference</h2>
      </div>
      <div class="impact__grid">
        <div class="impact__item counter-animate">
          <div class="impact__icon">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M16.5 6a4.5 4.5 0 11-9 0 4.5 4.5 0 019 0zM18.75 10.5a3.75 3.75 0 11-7.5 0h7.5zM12 13.5c-4.97 0-9 2.69-9 6v1.5h18v-1.5c0-3.31-4.03-6-9-6z"/></svg>
          </div>
          <div class="impact__number"><span data-counter="12">0</span></div>
          <div class="impact__suffix">Million</div>
          <div class="impact__label">People assisted annually</div>
        </div>
        <div class="impact__item counter-animate">
          <div class="impact__icon">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M11.645 20.91l-.007-.003-.022-.012a15.247 15.247 0 01-.383-.218 25.18 25.18 0 01-4.244-3.17C4.688 15.36 2.25 12.174 2.25 8.25 2.25 5.322 4.714 3 7.688 3A5.5 5.5 0 0112 5.052 5.5 5.5 0 0116.313 3c2.973 0 5.437 2.322 5.437 5.25 0 3.925-2.438 7.111-4.739 9.256a25.175 25.175 0 01-4.244 3.17 15.247 15.247 0 01-.383.219l-.022.012-.007.004-.003.001a.752.752 0 01-.704 0l-.003-.001z"/></svg>
          </div>
          <div class="impact__number"><span data-counter="50000" data-format="comma">0</span></div>
          <div class="impact__suffix">Volunteers</div>
          <div class="impact__label">Active across our network</div>
        </div>
        <div class="impact__item counter-animate">
          <div class="impact__icon">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M12 21a9.004 9.004 0 008.716-6.747M12 21a9.004 9.004 0 01-8.716-6.747M12 21c2.485 0 4.5-4.03 4.5-9S14.485 3 12 3m0 18c-2.485 0-4.5-4.03-4.5-9S9.515 3 12 3m0 0a8.997 8.997 0 017.843 4.582M12 3a8.997 8.997 0 00-7.843 4.582m15.686 0A11.953 11.953 0 0112 10.5c-2.998 0-5.74-1.1-7.843-2.918m15.686 0A8.959 8.959 0 0121 12c0 .778-.099 1.533-.284 2.253m0 0A17.919 17.919 0 0112 16.5c-3.162 0-6.133-.815-8.716-2.247m0 0A9.015 9.015 0 013 12c0-.778.099-1.533.284-2.253"/></svg>
          </div>
          <div class="impact__number"><span data-counter="190">0</span></div>
          <div class="impact__suffix">Countries</div>
          <div class="impact__label">Where we've provided aid</div>
        </div>
        <div class="impact__item counter-animate">
          <div class="impact__icon">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M12 6v12m-3-2.818l.879.659c1.171.879 3.07.879 4.242 0 1.172-.879 1.172-2.303 0-3.182C13.536 12.219 12.768 12 12 12c-.725 0-1.45-.22-2.003-.659-1.106-.879-1.106-2.303 0-3.182s2.9-.879 4.006 0l.415.33M21 12a9 9 0 11-18 0 9 9 0 0118 0z"/></svg>
          </div>
          <div class="impact__number">$<span data-counter="850">0</span></div>
          <div class="impact__suffix">Million Raised</div>
          <div class="impact__label">In the last fiscal year</div>
        </div>
      </div>
      <p class="impact__footnote">These figures represent real lives changed &mdash; families sheltered after storms, blood delivered to hospitals, and communities rebuilt stronger than before.</p>
    </div>
  </section>

  <!-- ===== PROGRAMS ===== -->
  <section class="section section--gray" id="programs">
    <div class="container">
      <div class="section__header">
        <span class="section__label">What We Do</span>
        <h2 class="section__title">Programs &amp; Services</h2>
        <p class="section__subtitle">From emergency response to long-term recovery, our programs address every phase of a disaster and build stronger, more resilient communities.</p>
      </div>
      <div class="programs__list">

        <div class="accordion__item active">
          <button class="accordion__header" aria-expanded="true">
            <span class="accordion__icon-wrapper" aria-hidden="true">
              <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24"><path d="M11.47 3.84a.75.75 0 011.06 0l8.69 8.69a.75.75 0 101.06-1.06l-8.689-8.69a2.25 2.25 0 00-3.182 0l-8.69 8.69a.75.75 0 001.061 1.06l8.69-8.69z"/><path d="M12 5.432l8.159 8.159c.03.03.06.058.091.086v6.198c0 1.035-.84 1.875-1.875 1.875H15.75v-4.5a.75.75 0 00-.75-.75h-6a.75.75 0 00-.75.75v4.5H5.625a1.875 1.875 0 01-1.875-1.875v-6.198a2.29 2.29 0 00.091-.086L12 5.432z"/></svg>
            </span>
            Disaster Relief
            <svg class="accordion__chevron" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" stroke="currentColor" stroke-width="2"><path stroke-linecap="round" stroke-linejoin="round" d="M19.5 8.25l-7.5 7.5-7.5-7.5"/></svg>
          </button>
          <div class="accordion__body">
            <div class="accordion__content">
              Rapid deployment of emergency shelter, food, water, and medical supplies to communities affected by natural disasters and conflict. Our response teams are on the ground within 24 hours.
            </div>
          </div>
        </div>

        <div class="accordion__item">
